'use strict';
window.BOOKSHOP_HOSTED=true;
window.shopReady=(async()=>{const screen=document.querySelector('#sign-in-screen');let status;try{const response=await fetch('/api/shop/status');status=await response.json();if(!response.ok)throw Error('setup');}catch{document.body.classList.add('auth-locked');screen.hidden=false;screen.innerHTML='<div class="login-card"><h1>Shop setup is not finished</h1><p>Please contact the shop owner to finish connecting the shared database.</p></div>';return new Promise(()=>{});}if(status.signedIn)return;document.body.classList.add('auth-locked');screen.hidden=false;screen.innerHTML='<div class="login-card"><h1>Welcome to Tiferes</h1><p>Enter the shop password to open orders and deliveries. Personal tasks have their own sign-in.</p><form id="shop-login-form"><label>Shop password<input type="password" name="password" autocomplete="current-password" required></label><p class="error" role="alert"></p><button class="primary">Open the shop</button></form></div>';return new Promise(resolve=>{const form=document.querySelector('#shop-login-form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('/api/shop/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:form.querySelector('input').value})});const result=await response.json();if(!response.ok)throw Error(result.error);form.reset();screen.hidden=true;document.body.classList.remove('auth-locked');resolve();}catch(err){form.querySelector('.error').textContent=err.message;}finally{button.disabled=false;}};});})();
